// Not thread-safe: read-modify-write is not one atomic step
class Counter {
    private int count = 0;
    void increment() { count = count + 1; }
}

// Thread-safe: the increment is a single atomic operation
class SafeCounter {
    private final AtomicInteger count = new AtomicInteger(0);
    void increment() { count.incrementAndGet(); }
}

